#!/usr/bin/env bash
# Reference solution, applied only by `astrona test` (the `testing:` block).
# `astrona run` never runs this. Taken from solution.md - if one changes,
# change the other.
set -euo pipefail

in_runner() { kubectl -n dac exec -i deploy/dac-runner -- sh -s; }
in_runner <<'GRADE'
set -u
. /opt/dac/grader-lib.sh
repo_change "Fix the shared panels and the dashboards" "mkdir -p lib/panels && printf '%s' '' | base64 -d > lib/panels/panels.cue && mkdir -p dashboards/cue && printf '%s' '' | base64 -d > dashboards/cue/team-overview.cue && mkdir -p dashboards/cue && printf '%s' '' | base64 -d > dashboards/cue/scrape-health.cue"
dac-run sh -c 'rm -rf built && percli dac build -d dashboards -ojson && percli apply -d built'
GRADE
